function selectRow(t){const e=t.classList.contains("selected-row"),s=t.parentElement.children;if(e)t.classList.remove("selected-row");else{for(const t of s)t.classList.remove("selected-row");t.classList.add("selected-row")}}document.addEventListener("DOMContentLoaded",t=>{document.querySelectorAll(".btn-nesting").forEach(t=>{t.addEventListener("click",async function(){const t=this.getAttribute("data-bs-target").replace("#pososta",""),e=document.getElementById(`pososta${t}`),s=this.querySelector("i"),o="true"===this.getAttribute("aria-expanded");if(s.classList.remove("bi-chevron-down","bi-chevron-up","rotate"),o?(s.classList.add("bi-chevron-up"),this.setAttribute("aria-expanded","false")):(s.classList.add("bi-chevron-down"),this.setAttribute("aria-expanded","true")),e.dataset.loaded)e.classList.toggle("d-none"),e.classList.contains("d-none")&&e.querySelectorAll(".selected-row").forEach(t=>t.classList.remove("selected-row"));else try{const s=await fetch(`/api/krathseis/getPosostaKrathseon/${t}`);if(!s.ok)throw new Error("Network response was not ok");const o=await s.json();let n='\n    <div class="nested-table-scroll-container">\n        <table class="table table-striped table-bordered table-sm table-hover nested-table mb-0">\n            <thead>\n                <tr>\n                    <th class="col-0-5 text-center nested-table-header">α/α</th>\n                    <th class="col-1 text-center nested-table-header">Ισχύει Από</th>\n                    <th class="col-1 text-center nested-table-header">Ισχύει Εως</th>\n                    <th class="col-1 text-right nested-table-header"><i class="bi bi-percent" style="font-size: 1.2rem; font-weight: 700"></i> Εργαζ/νου</th>\n                    <th class="col-1 text-right nested-table-header"><i class="bi bi-percent" style="font-size: 1.2rem; font-weight: 700"></i> Εργοδότη</th>\n                    <th class="col-1 text-right nested-table-header"><i class="bi bi-percent" style="font-size: 1.2rem; font-weight: 700"></i> ΣΥΝΟΛΟ</th>\n                    <th class="col-1 text-right nested-table-header"><i class="bi bi-currency-euro" style="font-size: 1.2rem; font-weight: 700"></i> Εργαζ/νου</th>\n                    <th class="col-1 text-right nested-table-header"><i class="bi bi-currency-euro" style="font-size: 1.2rem; font-weight: 700"></i> Εργοδότη</th>\n                    <th class="col-1 text-right nested-table-header"><i class="bi bi-currency-euro" style="font-size: 1.2rem; font-weight: 700"></i> ΣΥΝΟΛΟ</th>\n                    <th class="col-1 text-right nested-table-header">Αν. Όριο Παλιών</th>\n                    <th class="col-1 text-right nested-table-header">Αν. Όριο Νέων</th>\n                </tr>\n            </thead>\n\n            <tbody>',a={day:"2-digit",month:"2-digit",year:"numeric"},i=o.length+1;o.forEach(t=>{let e=new Date(t.isxyei_apo).toLocaleDateString("el-GR",a),s=new Date(t.isxyei_eos).toLocaleDateString("el-GR",a);i-=1,n+=`\n              <tr data-id="${t._id}">\n                <td class="col-0-5 text-right field-required" style="background-color: #19875450; font-size: 0.9vw;">${i.toFixed(0)}</td>\n                <td class="col-1 text-center" style="font-size: 0.9vw;">${e}</td>\n                <td class="col-1 text-center" style="font-size: 0.9vw;">${s}</td>\n                <td class="col-1 text-right" style="font-size: 0.9vw;">${t.pososto_ergazomenoy.toFixed(4)}</td>\n                <td class="col-1 text-right" style="font-size: 0.9vw;">${t.pososto_ergodoth.toFixed(4)}</td>\n                <td class="col-1 text-right field-required" style="background-color: #19875450; font-size: 0.9vw;">${t.synolo_pososton.toFixed(4)}</td>\n                <td class="col-1 text-right" style="font-size: 0.9vw;">${t.poso_ergazomenoy.toFixed(2)}</td>\n                <td class="col-1 text-right" style="font-size: 0.9vw;">${t.poso_ergodoth.toFixed(2)}</td>\n                <td class="col-1 text-right field-required" style="background-color: #ffee0127; font-size: 0.9vw;">${t.synolo_poson.toFixed(2)}</td>\n                <td class="col-1 text-right" style="font-size: 0.9vw;">${t.anotato_orio_palion.toFixed(2)}</td>\n                <td class="col-1 text-right" style="font-size: 0.9vw;">${t.anotato_orio_neon.toFixed(2)}</td>\n              </tr>`}),n+="\n            </tbody>\n        </table>\n    </div>",e.innerHTML=n,e.dataset.loaded="true"}catch(t){console.error("Failed to fetch pososta data:",t)}})})});